<?php
require_once __DIR__ . '/config.php'; require_admin(); verify_csrf();
$pdo=db(); $error=''; $action=$_GET['action']??'list'; $id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST') {
    $title=trim($_POST['book_title']??''); $client=trim($_POST['client_name']??'');
    $qty=filter_var($_POST['total_quantity']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
    $due=trim($_POST['due_date']??''); $priority=($_POST['priority']??'normal')==='urgent'?'urgent':'normal'; $notes=trim($_POST['notes']??'');
    if($title===''||!$qty) $error='Please enter a book title and a quantity greater than zero.';
    else {
        if(($_POST['form_action']??'')==='edit' && $id>0) {
            $s=$pdo->prepare("UPDATE production_jobs SET book_title=?,client_name=?,total_quantity=?,due_date=?,priority=?,notes=? WHERE id=?");
            $s->execute([$title,$client,$qty,$due?:null,$priority,$notes?:null,$id]); flash('Production job updated.'); redirect('jobs.php');
        } else {
            $code='BP-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(2)));
            $pdo->beginTransaction();
            try {
                $s=$pdo->prepare("INSERT INTO production_jobs (job_code,book_title,client_name,total_quantity,due_date,priority,notes,created_by) VALUES (?,?,?,?,?,?,?,?)");
                $s->execute([$code,$title,$client,$qty,$due?:null,$priority,$notes?:null,current_user()['id']]); $jobId=(int)$pdo->lastInsertId();
                foreach(stages() as $stage=>$meta) {
                    $s=$pdo->prepare("INSERT INTO production_updates (job_id,stage,status,completed_quantity) VALUES (?,?,'pending',0)"); $s->execute([$jobId,$stage]);
                    $s=$pdo->prepare("INSERT INTO production_history (job_id,stage,status,completed_quantity,note,changed_by) VALUES (?,?,'pending',0,'Job created',?)"); $s->execute([$jobId,$stage,current_user()['id']]);
                }
                $pdo->commit(); flash('New production job created successfully.'); redirect('jobs.php');
            } catch(Throwable $e) { $pdo->rollBack(); $error='Could not create job. Please try again.'; }
        }
    }
}
$edit=null;
if($action==='edit' && $id) { $s=$pdo->prepare("SELECT * FROM production_jobs WHERE id=?");$s->execute([$id]);$edit=$s->fetch();if(!$edit){flash('Job not found.','error');redirect('jobs.php');} }
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
$jobs=$pdo->query("SELECT j.*, (SELECT COUNT(*) FROM production_updates u WHERE u.job_id=j.id AND u.status='completed') AS done_stages FROM production_jobs j ORDER BY j.created_at DESC")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Production Jobs | <?=e(APP_NAME)?></title><link rel="stylesheet" href="assets/style.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar"><a class="side-brand" href="dashboard.php"><div class="brand-mark">BP</div><div><strong>BOOKPRINTERS</strong><small>& SHREEPUBLICATIONS</small></div></a><div class="side-label">WORKSPACE</div><a class="nav-link" href="dashboard.php"><span>▦</span> Overview</a><a class="nav-link active" href="jobs.php"><span>▤</span> Production jobs</a><a class="nav-link" href="employees.php"><span>♙</span> Employees & access</a><div class="sidebar-bottom"><div class="user-mini"><div class="avatar"><?=e(strtoupper(substr(current_user()['full_name'],0,1)))?></div><div><strong><?=e(current_user()['full_name'])?></strong><small>Administrator</small></div></div><a class="nav-link logout" href="logout.php"><span>↪</span> Sign out</a></div></aside><main class="main"><header class="topbar"><div><p class="eyebrow">WORKSPACE / PRODUCTION</p><h1>Production jobs</h1></div><a class="btn secondary" href="dashboard.php">← Dashboard</a></header><?php if($flash): ?><div class="alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif; ?><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?>
<?php if($action==='new'||$action==='edit'): ?><section class="form-panel"><div class="panel-heading"><div><h2><?=$edit?'Edit production job':'Create a production job'?></h2><p class="muted small">Add one order here. Its five production stages are created automatically.</p></div><a class="btn secondary" href="jobs.php">Cancel</a></div><form method="post" class="job-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="form_action" value="<?=$edit?'edit':'new'?>"><div class="form-grid"><div class="field wide"><label>Book title / product name *</label><input name="book_title" required maxlength="200" value="<?=e($edit['book_title']??'')?>" placeholder="e.g. Rajasthan Geography – Volume 1"></div><div class="field"><label>Client / publisher name</label><input name="client_name" maxlength="160" value="<?=e($edit['client_name']??'')?>" placeholder="Customer or publisher"></div><div class="field"><label>Total order quantity (copies) *</label><input type="number" name="total_quantity" min="1" required value="<?=e($edit['total_quantity']??'')?>" placeholder="e.g. 2000"></div><div class="field"><label>Target completion date</label><input type="date" name="due_date" value="<?=e($edit['due_date']??'')?>"></div><div class="field"><label>Priority</label><select name="priority"><option value="normal" <?=($edit['priority']??'normal')==='normal'?'selected':''?>>Normal</option><option value="urgent" <?=($edit['priority']??'')==='urgent'?'selected':''?>>Urgent</option></select></div><div class="field wide"><label>Job notes / special instructions</label><textarea name="notes" rows="3" placeholder="Paper type, cover details, customer instructions..."><?=e($edit['notes']??'')?></textarea></div></div><?php if(!$edit): ?><div class="workflow-preview"><strong>Production route</strong><div><?php foreach(stages() as $s=>$m): ?><span><?=e($m['label'])?></span><?php if($m['step']<5): ?><i>→</i><?php endif; ?><?php endforeach; ?></div></div><?php endif; ?><button class="btn primary" type="submit"><?=$edit?'Save changes':'Create job & start tracking'?> →</button></form></section>
<?php else: ?><section class="welcome-row"><div><h2>All book orders</h2><p class="muted">Create jobs and monitor progress from start to finish.</p></div><a class="btn primary" href="jobs.php?action=new">＋ Create production job</a></section><section class="panel"><div class="panel-heading"><div><h3>Production register</h3><p class="muted small"><?=count($jobs)?> job(s) in the system</p></div><div class="search-wrap"><span>⌕</span><input id="jobSearch" placeholder="Search book or job code..."></div></div><div class="table-wrap"><table id="jobsTable"><thead><tr><th>Job / Book title</th><th>Quantity</th><th>Target date</th><th>Priority</th><th>Progress</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($jobs as $j):$pct=(int)round((int)$j['done_stages']/5*100); ?><tr><td><div class="book-cell"><div class="book-icon">▤</div><div><strong><?=e($j['book_title'])?></strong><small><?=e($j['job_code'])?><?= $j['client_name']?' · '.e($j['client_name']):'' ?></small></div></div></td><td><?=number_format((int)$j['total_quantity'])?> copies</td><td><?=e($j['due_date']?:'—')?></td><td><span class="status <?=$j['priority']==='urgent'?'urgent':'normal'?>"><?=e(ucfirst($j['priority']))?></span></td><td><div class="progress-meta"><span><?=$j['done_stages']?> / 5 stages</span><strong><?=$pct?>%</strong></div><div class="progress-track"><span style="width:<?=$pct?>%"></span></div></td><td><?=e(date('d M Y',strtotime($j['created_at'])))?></td><td><a class="btn small-btn secondary" href="jobs.php?action=edit&id=<?=(int)$j['id']?>">Edit</a> <a class="btn small-btn primary" href="job.php?id=<?=(int)$j['id']?>">Details</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$jobs): ?><div class="empty-state"><div>▤</div><h3>No jobs created yet</h3><p>Create your first book production job to start tracking.</p></div><?php endif; ?></div></section><?php endif; ?><footer class="footer">© <?=date('Y')?> BookPrinters & ShreePublications <span>Production made visible.</span></footer></main></div></body></html>
